For all $ n\ge 1$, there are isomorphisms of graded commutative $k$-algebras

\begin{align*}
   {\rm HO}_\bullet(U\gl_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_1,\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\,,\\
    {\rm HO}_\bullet(U\mathfrak{sl}_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\ .
\end{align*}

Let $k$ be an arbitrary commutative ring. For any abelian group ${\mathcal A}$ and any pointed connected space $X$, there is a natural isomorphism

\begin{equation} 
\la{isoDA}
{\rm HR}_\bullet(X, D_k({\mathcal A}))\,\cong\,\mathrm H_\bullet\big(\Omega\,\SPi(X, {\mathcal A});\,k\big)\ , 
\end{equation}

where $\Omega\,\SPi(X, A)$ is the based loop space of the McCord-Dold-Thom space \eqref{spxa}. Consequently,

$$ {\rm HR}_\bullet(X, D_k({\mathcal A}))\,\cong\,\mathrm H_\bullet\Big(\prod_{n \geq 1}K\big(\tilde{\mathrm H}_n(X, {\mathcal A}),\,n-1\big);\,k\Big)\,. 
$$

Given $A\in \mathtt{DGA}^{\ob}_{S}$ and $B\in \mathtt{DGA}^{\ob}_{\mathcal{M}_n(k)}$, with structure maps $P: S\to A$ and $Q: \mathcal{M}_n(k)\to B$, we want to show that there is a natural bijection of sets $$\Hom_{\mathtt{DGA}^{\ob}_{\mathcal{M}_n(k)}}  (A\ast_S M_n(k),B)= \Hom_{\mathtt{DGA}^{\ob}_S}(A,\rho^*(B))\ .$$

An element $f\in \Hom_{\mathtt{DGA}^{\ob}_S}(A,\rho^*(B))$ is a map $f\in \Hom_{\mathtt{DGA}^{\ob}_k}(A,B)$ such that $f\circ P = Q\circ \rho$. Since $A\ast_S \mathcal{M}_n(k)$ is the coproduct, a pair of maps $f: A\to B$ and $Q: \mathcal{M}_n(k)\to B$ such that $f\circ p=Q\circ \rho$ determine a unique map $A\ast_S \mathcal{M}_n(k)\to B$. This yields a natural map of sets 

\begin{equation} \la{forw} \Hom_{\mathtt{DGA}^{\ob}_S}(A,\rho^*(B))\to \Hom_{\mathtt{DGA}^{\ob}_{\mathcal{M}_n(k)}}(A\ast_S\mathcal{M}_n(k),B)\ . \end{equation}

Conversely, for any $\varphi \in \Hom_{\mathtt{DGA}^{\ob}_{\mathcal{M}_n(k)}}(A \ast_S \mathcal{M}_n(k), B)$, its restriction to $A$ via the homomorphism $A \to A \ast_S \mathcal{M}_n(k)$ in $\mathtt{DGA}^{\ob}_S$ determines a unique homomorphism of involutive DG algebras $A \to B$ over $S$. This gives a natural map of sets 

\begin{equation} \la{back}\Hom_{\mathtt{DGA}^{\ob}_{\mathcal{M}_n(k)}}(A\ast_S\mathcal{M}_n(k),B) \to \Hom_{\mathtt{DGA}^{\ob}_S}(A,\rho^*(B))\ . \end{equation}

It is easy to check that the maps \eqref{forw} and \eqref{back} are mutual inverses.

\la{trep}
 (a) The functors $(S\backslash \mbox{--})^{\ob}_n\,:\,  \mathtt{DGA}^{\ob}_S \rightleftarrows \mathtt{DGCA}_k \,:\, \mathcal{M}_n(-)$ form a Quillen pair.\\
  (b) The functor $(S \backslash \mbox{--})^{\ob}_n$ has a total left derived functor
      $$\mathbb{L}(S \backslash \mbox{--})^{\ob}_n\,:\,{\mathtt{Ho}}(\mathtt{DGA}^{\ob}_S) \rightarrow {\mathtt{Ho}}(\mathtt{DGCA}_k) \,,\,\,\,\, (S \backslash A) \mapsto Q(S \backslash A)_n\,,\,\,\,\, \gamma f \mapsto \gamma(\tilde{f}^{\ob}_n) \,\text{.}$$
       Here, $Q(S \backslash A)$ denotes any choice of cofibrant resolution of $(S \backslash A)$ in $\mathtt{DGA}^{\ob}_S$ and
$\tilde{f}$ denotes any cofibrant lifting of $f$ in $\mathtt{DGA}^{\ob}_S$. \\
(c) For any $S \backslash A$ in $\mathtt{DGA}^{\ob}_S$ and for any $B \in \mathtt{DGCA}_k$,
\begin{equation*}
\la{S2E15}
\Hom_{{\mathtt{Ho}}(\mathtt{DGCA}_k)}(\mathbb{L}(S \bs A)^{\ob}_n,\, B) \cong
\Hom_{{\mathtt{Ho}}(\mathtt{DGA}^{\ob}_S)}(A,\mathcal{M}_n(B))\ .
\end{equation*}

\la{hopushout}
There is a homotopy commutative diagram

\begin{equation}
\la{drepd2}
\begin{diagram}[small, tight]
\mathbb{L}(S \bs A)^{\ob}_n           &  \rTo^{\,\mathbb{L}(f)_n^{\ob}\,}        & \mathbb{L}(S \bs B)^{\ob}_n\\
\dTo^{\mathbb{L}(\rho)_n} &                    & \dTo \\
k                &  \rInto            & \mathbb{L}( A \bs B)^{\ob}_n
\end{diagram}
\end{equation}

which is a cocartesian square in $ {\mathtt{Ho}}(\mathtt{DGCA}_k) $.

\la{S2L9}
The commutative diagram

\begin{equation}
\la{drepd11}
\begin{diagram}[small, tight]
(S\bs A)^{\ob}_n               &  \rTo^{\,(f)^{\ob}_n  \,}            & (S\bs B)^{\ob}_n  \\
\dTo^{(\varrho)^{\ob}_n  } &                                   & \dTo \\
k                       &  \rInto                           & (A\bs B)^{\ob}_n  
