\la{simp}
For any $A\in \mathtt{Alg}^{\ob}_k$, there is a natural isomorphism 
$$ \mathrm{HR}_{\bullet}^{\ob}(A, k^n)\cong \mathrm{HR}_{\bullet}^{\ob}(A, k^n)^{\mathtt{s}} \,.$$

\la{goodhom}

If $h: A \rightarrow B \otimes \Omega$ is a morphism in $\mathtt{DGA}^{\ob}_S$ such that $h(0)=f$ and $h(1)=g$, then
$\mathcal{C}(f) \sim \mathcal{C}(g)$ in $\mathtt{Com}_k$.

\la{HDAto0}
For $A \in \mathtt{DGA}^{\ob}_k$, there is an isomorphism of homologies 
\[ {\rm HD}_\bullet(A \bs 0)\,\cong\, {\rm HD}_\bullet(A)\ .\]

\la{mordih}

The functor $\widetilde{\mathcal{C}}$ has a total left derived functor
$$\mathbb{L}\widetilde{\mathcal{C}}\,:\,{\mathtt{Ho}}(\mathtt{Mor}(\mathtt{DGA}^{\ob}_k)) \rightarrow \mathcal D(k)\,,\,\,\,\, (S \bs A) \mapsto \mathcal{C}(Q(QS \bs A)) \,\text{.}$$
 Here, $QS$ is a cofibrant resolution of $S$ in $\mathtt{DGA}^{\ob}_k$ and $Q(QS \bs A)$ is a cofibrant resolution of $A$ in
$\mathtt{DGA}^{\ob}_{QS}$.  Unpacking notation, in ~\cite{BKR} this was equivalently written 
\begin{equation}
\la{isff}
\mathbb{L}\widetilde{\mathcal{C}}(S \bs A) = \cn[(QS)_\n \to Q(QS\bs A)_\n]\ ,
\end{equation}

\la{t3.3c}
For $A \in \mathtt{DGA}^{\ob}_k$, there is a (natural) isomorphism of homologies for all $n$
\[ {\rm HD}_{n-1}(k \bs A)\,\cong\, \overline{\rm HD}_n(A)\ .\]

Recall that, when $V$ is concentrated in degree $0$, we have the invariant subfunctor of $ (\mbox{---})_n^{\ob} $:

$$
((\mbox{---})_n^{\ob})^{G} :\ \mathtt{DGA}_k \to \mathtt{DGCA}_k\ ,\quad A \mapsto ((A)_n^{\ob})^{G}\ .
$$

It is clear from \eqref{E1S4} that the natural transformation $ {\rm{Tr}}_n$ maps $ \mathcal{C} $ to this subfunctor:

\begin{equation}
\la{E8S4}
{\rm{Tr}}_n:\ \mathcal{C} \to \overline{(\mbox{---})}_n^{\ob, G}
\end{equation}

Now, by Theorem~\ref{inv}, $\, ((\mbox{---})_n^{\ob})^G $ has a total left derived functor, which is isomorphic to the invariant subfunctor $ (\mathbb{L}(\mbox{---})_n^{\ob}) ^G$ of $ \mathbb{L}(\mbox{---})_n^{\ob} $. Hence,
\eqref{E8S4} descends to the homotopy categories, i.e. induces a natural transformation
$\, {\rm{Tr}}_n^{\ob}:\, \mathbb{L}\mathcal{C} \to \overline{(\mathbb{L}(\mbox{---})}_n^{\ob})^G\,$. On the homology level, this gives

\begin{equation}
\la{E9S4}
\boldsymbol{\Lambda} {\rm{Tr}}_n^{\ob}(A)_\bullet :\ \boldsymbol{\Lambda}(\mathrm{HD}(A)) \to \mathrm{HR}^{\ob}_{\bullet}(A, k^n)^{G}\ ,
\end{equation}

which is the statement of proposition.

{\cite[Theorem 4.3]{Ke}}
The pair of adjoint functors

\begin{equation} \la{cbb} \mathbf{\Omega}\,:\,  \mathtt{DGC}_{k/k} \rightleftarrows \mathtt{DGA}_{k/k}\,:\,\boldsymbol{B} \end{equation}

is a Quillen pair. In particular, the functors~\eqref{cbb} induce mutually inverse equivalences between homotopy categories

$$ \mathbb{L} \mathbf{\Omega}\,:\,{\mathtt{Ho}}(\mathtt{DGC}_{k/k}) \,\cong\, {\mathtt{Ho}}(\mathtt{DGA}_{k/k})\,:\, \mathbb{R} \boldsymbol{B} \,\text{.}$$

\la{basskc}
$(i)$ The skew involution on a skew involutive coaugmented DG coalgebra $C \in \mathtt{DGC}_{k/k}$ restricts to a skew involution on $\overline{C}\in \mathtt{DGC}$.\\

$(ii)$ A skew involution on (the non-counital) DG coalgebra $\overline{C}\in \mathtt{DGC}$ extends by linearity to a skew involutive structure on $C \in \mathtt{DGC}_{k/k}$ such that $\sigma(1)=-1$.

\la{twbijinv}
There are natural bijections of sets

$$ \Hom_{\mathtt{DGA}^{\ob}_{k/k}}(\mathbf{\Omega}(C), R)\,\cong\,\mathtt{Tw}(\overline{C},\overline{R})^{\mathbb{Z}_2}\,\cong\, \Hom_{\mathtt{DGC}^{\ob}_{k/k}}(C, \boldsymbol{B}(R)) \,\text{.}$$

\la{kosdualinv}
The pair of adjoint functors

\begin{equation} \la{icbb} \mathbf{\Omega}\,:\,  \mathtt{DGC}^{\ob}_{k/k} \rightleftarrows \mathtt{DGA}^{\ob}_{k/k}\,:\,\boldsymbol{B} \end{equation}

is a Quillen pair. In particular, the functors~\eqref{cbb} induce mutually inverse equivalences between homotopy categories

$$ \mathbb{L} \mathbf{\Omega}\,:\,{\mathtt{Ho}}(\mathtt{DGC}^{\ob}_{k/k}) \,\cong\, {\mathtt{Ho}}(\mathtt{DGA}^{\ob}_{k/k})\,:\, \mathbb{R} \boldsymbol{B} \,\text{.}$$

We begin by proving the first part. Since $\mathbf{\Omega}(C)$ is cofibrant in $\mathtt{DGA}^{\ob}_{k/k}$ (see the preliminaries before Theorem \ref{kosdualinv}), it suffices to check that $(\mathbf{\Omega}(C))^{\ob}_n\,\cong\, {\mathscr C}({\gl}^{+,\ast}_n(\overline{C});k)$ in $\mathtt{DGCA}_{k/k}$. Now, for any $B \in \mathtt{DGCA}_{k/k}$,
\begin{equation} \la{eqinvadj1} \Hom_{\mathtt{DGCA}_{k/k}}((\mathbf{\Omega}(C))^{\ob}_n\,,\,B)\,\cong\, \Hom_{\mathtt{DGA}^{\ob}_{k/k}}( \mathbf{\Omega}(C)\,,\,\widetilde{\mathcal{M}}_n(B)) \,\text{.} \end{equation}
On the other hand, by Lemma~\ref{twbijinv}
\begin{equation} \la{eqinvadj2}\Hom_{\mathtt{DGA}_{k/k}}( \mathbf{\Omega}(C)\,,\,\widetilde{\mathcal{M}}_n(B))\,\cong\,\mathtt{Tw}(\overline{C}\,,\,\mathcal{M}_n(\bar{B}))^{\mathbb{Z}_2} \,,\end{equation}
where the $\mathbb{Z}_2$-action on $\mathtt{Tw}(\overline{C}\,,\,\mathcal{M}_n(\bar{B}))$ is induced by the $\mathbb{Z}_2$-action on $\HOM(\overline{C}\,,\,\mathcal{M}_n(\bar{B}))$ (see Lemma \ref{invHom}). Since the natural isomorphism 
$$\HOM(\overline{C}\,,\,\mathcal{M}_n(\bar{B})) \,\cong\, \HOM(\mathcal{M}_n^{\ast}(\overline{C}),\overline{B})$$
is an isomorphism of involutive DG-algebras (and therefore, an isomorphism of DG Lie algebras with $\mathbb{Z}_2$-action), there are natural bijections 

\begin{equation} \la{eqinvadj3} \mathtt{Tw}(\overline{C}\,,\,\mathcal{M}_n(\bar{B}))^{\mathbb{Z}_2} \,\cong\, \mathtt{Tw}(\mathcal{M}_n^{\ast}(\overline{C})\,,\,\bar{B})^{\mathbb{Z}_2}\,\cong\, \mathtt{Tw}(\gl_n^{+,\ast}(\overline{C})\,,\,\bar{B}) \,,\end{equation}

where the last bijection is a consequence of the DG Lie algebra isomorphism

$$\HOM(\mathcal{M}_n^{\ast}(\overline{C}),\overline{B})^{\mathbb{Z}_2} \,\cong\, \HOM(\gl_n^{+,\ast}(\overline{C}),\bar{B})\ .$$

It follows from \eqref{eqinvadj1}, \eqref{eqinvadj2} and \eqref{eqinvadj3} that there is a natural bijection 

\begin{equation} \la{eqinvadj4} \Hom_{\mathtt{DGCA}_{k/k}}((\mathbf{\Omega}(C))^{\ob}_n\,,\,B)\,\cong\, \mathtt{Tw}(\gl_n^{+,\ast}(\overline{C})\,,\,\bar{B})\ . \end{equation}

The right hand side of \eqref{eqinvadj4} is in natural bijection with $\Hom_{\mathtt{DGCA}_{k/k}}({\mathscr C}({\gl}^{+,\ast}_n(\overline{C});k), B)$ (see, for example, \cite[Sec. 6.3.4]{BFPRW}). The formula for $\DRep_n^{\ob}(A)$ then follows from the Yoneda lemma. To prove the formula for $\DRep_n^{\ob}(A)^G$, note that the Lie algebra of $G$ is precisely $\gl_n^{-}(k)$ (which is the $k$-linear dual of
$\gl_n^{+,*}(k)$). Then, as in the proof of~\cite[Theorem 3.2]{BFPRW}, note that ${\mathscr C}({\gl}^{+,*}_n(\overline{C});k)^G$ is precisely ${\mathscr C}(\gl^{+,*}_n(C), \gl^{+,*}_n(k);k)$. 
The remaining formulas for representation homologies then follow immediately.

