& \rdTo_{i^*} &                         & \ruDotsto &\\
&                  & \mathrm{HO}_\bullet(A)        & &
 \end{diagram}
 \end{equation*}

inducing a {\rm homomorphism} of graded commutative $k$-algebras with respect to the Graves structure on $\mathrm{HO}_\bullet(A)$:

\begin{equation}
\la{SRAA}
\mathrm{Tr}_{\rm hOct}(A)_\bullet:\ \mathrm{HO}_\bullet(A)\, \to\, \mathrm{HR^{\ob}_{\bullet}}(A, k) \ 
\end{equation}

Since $\overline{C}$ is cocommutative, the Lie cobracket on $\overline{C}$ vanishes (see Section \ref{CEThm}). Hence, the Lie cobracket on $\overline{C}^+$ vanishes. Further note that $\gl^{+,\ast}_1(\overline{C}) \cong \overline{C}^+$ (as Lie coalgebras). Hence, there is an isomorphism of graded commutative algebras ${\mathscr C}(\gl_1^{+,\ast}(\overline{C});k) \cong \Lambda_k(\overline{C}^+[-1])$. By Theorem \ref{invmain},

\begin{equation} \la{hr1ua} \mathrm{HR^{\ob}_{\bullet}}(U\mathfrak{a},k) \,\cong\, \mathrm H_\bullet[\Lambda_k(\overline{C}^+[-1])]\ .\end{equation}
 It follows that there is a chain of natural isomorphisms 

\begin{equation}
\la{isoLie}
{\rm HO}_\bullet(U\mathfrak{a}) \,\cong\, \mathrm{HR^{\ob}_{\bullet}}(U\mathfrak{a},k) \,\cong\,  \mathrm H_\bullet[\Lambda_k(\overline{C}^+[-1])] \,\cong\, 
\Lambda_k[\overline{\mathrm{H}}^{\rm ev}_{\bullet+1}(\mathfrak{a};k)]\ .
\end{equation}

The first isomorphism in \eqref{isoLie} follows from Proposition \ref{tA}, the second is \eqref{hr1ua}, and the last one is a consequence of the well-known fact that the graded symmetric algebra functor $\Lambda_k$ commutes with homology when $k$ is a field of characteristic $0$ (see, e.g. \cite[Appendix B, Prop. 2.1]{Q}). This proves the desired theorem.

Let $V$ be an finite dimensional $k$-vector space equipped with an involution (i.e., a linear map $\sigma: V \to V$ such that $\sigma^2={\rm{Id}}$). Let $V_+$ and $V_{-}$ denote the $+1$ and $-1$ eigenspaces of $\sigma$ respectively. Then ${\rm{Sym}}(V)$ acquires an involution whose restriction to $V$ is $\sigma$. For any (graded) $k$-vector space $W$, let $\Lambda^{\rm odd}(W)$ (resp., $\Lambda^{\rm ev}(W)$) denote the direct sum of all odd (resp., even) graded symmetric powers of $W$.

\begin{cor} \la{hosym}
There is an isomorphism of graded commutative $k$-algebras
$${\rm HO}_\bullet({\rm{Sym}}(V))\,\cong\, \bigwedge_k\left[\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]\right]\ .$$    
\end{cor}

\begin{proof}
Let $\mathfrak{a}=V$ equipped with the trivial Lie bracket. Then, $\mathfrak{a}$ is an involutive Lie algebra, and $U\mathfrak{a} \cong {\rm{Sym}}(V)$ as involutive algebras. ${\mathscr C}(\mathfrak{a};k)=\Lambda_k(V[1])$, with trivial differential and skew involution whose corestriction to $V[1]$ is the involution $\sigma$ on $V$. To compute ${\mathscr C}(\mathfrak{a};k)_+$, we consider its graded $k$-linear dual $E:=\Lambda_k(V^{\ast}[-1])$. This graded commutative $k$-algebra is equipped with a skew involution whose restriction to $V^{\ast}[-1]$ is the operator induced by $\sigma$ on $V^{\ast}$. Abusing notation, denote this skew involution on $E$ by $\sigma$ as well. If $V^\ast_+$ and $V^\ast_-$ denote the $+1$ and $-1$ eigenspaces of $\sigma$ on $V^\ast$ respectively, $E \cong \Lambda(V^{\ast}_+[-1]) \otimes \Lambda(V^{\ast}_-[-1])$. Since $\sigma$ is a skew involution on the graded commutative algebra $E$, 

$$\sigma(x_1 \ldots x_n)\,=\,(-1)^{n-1}\sigma(x_1)\ldots \sigma(x_n)\,,\qquad \forall \,x_1,\ldots\,x_n\,\in\,E\ .$$

Hence, on the direct summand $\Lambda^i(V^{\ast}_+[-1]) \otimes \Lambda^j(V^{\ast}_-[-1])$ of $E$, $\sigma$ acts by multiplication by $(-1)^{i+j-1}(-1)^j=(-1)^{i-1}$. It follows that the $+1$-eigenspace of the skew involution on $E$ is $\Lambda^{\rm odd}(V^{\ast}_+[-1]) \otimes \Lambda(V^{\ast}_-[-1])$. Dually, ${\mathscr C}(\mathfrak{a};k)_+\,=\,\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])$. Hence, $\overline{\mathrm{H}}^{\rm ev}_\bullet(\mathfrak{a};k) \,\cong\, \Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])$. The desired lemma now follows from Theorem \ref{houainv}.
\end{proof}

\begin{remark} Note that the commutative square of functors
$$
\begin{diagram}[small]
\Delta C^{\rm op} &\rTo^{i}&\Delta S\\
 \dInto & & \dInto\\
 \Delta D^{\rm op} &\rTo^{i}& \Delta H\\
\end{diagram}
$$
induces a commutative diagram of homologies 
\begin{equation} \la{hcdso}
\begin{diagram}[small]
\overline{{\rm HC}}_\bullet(A) &\rTo^{i^*} & {\rm HS}_\bullet(A)\\
\dTo & & \dTo\\
\overline{{\rm HD}}_\bullet(A) &\rTo^{i^*} & {\rm HO}_\bullet(A)\\
\end{diagram}
\end{equation}
for any $A \in \mathtt{DGA}^{\ob}_{k/k}$. For $A={\rm{Sym}}(V)$ where $V$ is equipped with an involution as above, by the Hochschild-Kostant-Rosenberg theorem we have 

\begin{equation*}
\overline{\rm HC}_\bullet(A)\,\cong\, \Omega^{\bullet}_{A/k}/d\Omega^{\bullet-1}_{A/k}\,,\qquad \overline{\rm HD}_\bullet(A)\,\cong\,(\Omega^{\bullet}_{A/k})_+/(d\Omega^{\bullet-1}_{A/k})_+\,,\end{equation*}

where $(\Omega^p_{A/k})_+$ (resp., $(d\Omega^{p-1}_{A/k})_+$) stands for the subspace of $\Omega^p_{A/k}$ (resp., $d\Omega^{p-1}_{A/k}$) on which the involution on $\Omega^{\bullet}_{A/k}$ induced by the involution on $V$ acts with eigenvalue $(-1)^p$ (see \cite{SV} for the second isomorphism in the dihedral case). With these identifications, and by \cite{BR22c} and Corollary \ref{hosym} above, the diagram \eqref{hcdso} is identified with 
\begin{equation} \la{hcdso2}
\begin{diagram}
\Omega^{\bullet}_{A/k}/d\Omega^{\bullet-1}_{A/k} & \rTo^{{\rm{Tr}}} & \bigwedge_k\left[\big(\Lambda^{\geq 1}(V[1])\big)[-1]\right]\\
\dTo & & \dTo\\
(\Omega^{\bullet}_{A/k})_+/(d\Omega^{\bullet-1}_{A/k})_+ & \rTo & \bigwedge_k\left[\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]\right]\\
\end{diagram}
\end{equation}

where the left vertical arrow is a projection to the direct summand, while the right vertical arrow is a quotient map: note that the space of generators $\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]$ of ${\rm HO}_\bullet(A)$ is a direct summand of the space of generators $\big(\Lambda^{\geq 1}(V[1])\big)[-1]$ of ${\rm HS}_\bullet(A)$. It follows from \eqref{hcdso2} and \cite[Theorem 4.2]{BFPRW2} that the map $i^{\ast}\,:\,\overline{\rm HD}_\bullet({\rm{Sym}}(V)) \to {\rm HO}_\bullet({\rm{Sym}}(V))$ can be expressed in terms of certain explicit differential operators on $\Omega^{\bullet}({\rm{Sym}}(V))$.

\end{remark}

\la{hosym}
There is an isomorphism of graded commutative $k$-algebras
$${\rm HO}_\bullet({\rm{Sym}}(V))\,\cong\, \bigwedge_k\left[\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]\right]\ .$$

