\begin{diagram}
\Omega^{\bullet}_{A/k}/d\Omega^{\bullet-1}_{A/k} & \rTo^{{\rm{Tr}}} & \bigwedge_k\left[\big(\Lambda^{\geq 1}(V[1])\big)[-1]\right]\\
\dTo & & \dTo\\
(\Omega^{\bullet}_{A/k})_+/(d\Omega^{\bullet-1}_{A/k})_+ & \rTo & \bigwedge_k\left[\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]\right]\\
\end{diagram}
\end{equation}

where the left vertical arrow is a projection to the direct summand, while the right vertical arrow is a quotient map: note that the space of generators $\big(\Lambda^{\rm odd}(V_+[1]) \otimes \Lambda(V_-[1])\big)[-1]$ of ${\rm HO}_\bullet(A)$ is a direct summand of the space of generators $\big(\Lambda^{\geq 1}(V[1])\big)[-1]$ of ${\rm HS}_\bullet(A)$. It follows from \eqref{hcdso2} and \cite[Theorem 4.2]{BFPRW2} that the map $i^{\ast}\,:\,\overline{\rm HD}_\bullet({\rm{Sym}}(V)) \to {\rm HO}_\bullet({\rm{Sym}}(V))$ can be expressed in terms of certain explicit differential operators on $\Omega^{\bullet}({\rm{Sym}}(V))$.

Recall that as graded algebras, $\mathrm H^\bullet(\gl_n;k)\,\cong\,\Lambda_k(\omega_1,\omega_3,\ldots,\omega_{2n-1})$ and $\mathrm H^{\bullet}(\mathfrak{sl}_n;k)\,\cong\,\Lambda_k(\omega_3,\omega_5,\ldots,\omega_{2n-1})$, where $\omega_{2i-1}$ is the class of the cocycle 

$$\tilde{\omega}_{2i-1}: (X_1,\ldots,X_{2i-1}) \mapsto \sum_{\tau \in S_{2i-1}} {\rm sgn}(\tau){\rm{Tr}}(X_{\tau(1)}X_{\tau(2)}\ldots X_{\tau(2i-1)})\ .$$
Dually, $\mathrm H_\bullet(\gl_n(k);k) \,\cong\,\Lambda_k(\xi_1,\xi_3,\ldots,\xi_{2n-1})$ and $\mathrm H_\bullet(\mathfrak{sl}_n(k);k)\,\cong\,\Lambda_k(\xi_3,\xi_5,\ldots,\xi_{2n-1})$ (as graded cocommutative coalgebras), where the cogenerator $\xi_{2i-1}$ in degre $2i-1$ is dual to the cohomology class $\omega_{2i-1}$. Note that any involution $\sigma$ on $\gl_n(k)$ that is (the restriction of) an involution on the associative algebra $\mathcal{M}_n(k)$ of $n \times n$-matrices with entries in $k$ restricts to an involution on $\mathfrak{sl}_n(k)$.

\begin{cor} \la{hougl}
For any involution on $\gl_n(k)$ that is the restriction of an involution on $\mathcal{M}_n(k)$ as above,

\begin{align*}
   {\rm HO}_\bullet(U\gl_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_1,\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\,,\\
    {\rm HO}_\bullet(U\mathfrak{sl}_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\ .
\end{align*}
\end{cor}
\begin{proof}
Abusing notation, let $\sigma$ denote the skew involution on $\mathrm H^{\bullet}(\gl_n(k);k)$ induced by the involution on $\gl_n(k)$. Let $s$ denote the permutation $j \mapsto 2i-j$ in $S_{2i-1}$. Note that ${\rm sgn}(s)=(-1)^{i-1}$. Then, 
\begin{align*}
\sigma\tilde{\omega}_{2i-1}(X_1,\ldots,X_{2i-1}) &= \tilde{\omega}(\sigma(X_1),\ldots,\sigma(X_{2i-1}))\\
 &=\sum_{\tau \in S_{2i-1}} {\rm sgn}(\tau){\rm{Tr}}(\sigma(X_{\tau(1)})\sigma(X_{\tau(2)})\ldots \sigma(X_{\tau(2i-1)}))\\
 &= \sum_{\tau \in S_{2i-1}} {\rm sgn}(\tau){\rm{Tr}}(\sigma(X_{\tau(2i-1)}X_{\tau(2i-2)}\ldots X_{\tau(1)}))\\
 &= \sum_{\tau \in S_{2i-1}} {\rm sgn}(\tau){\rm{Tr}}(X_{\tau(2i-1)}X_{\tau(2i-2)}\ldots X_{\tau(1)})\\
 &= \sum_{\tau \in S_{2i-1}} {\rm sgn}(\tau){\rm{Tr}}(X_{\tau \circ s(1)}X_{\tau \circ s(2)}\ldots X_{\tau \circ s(2i-1)})\\
 &= (-1)^{i-1}\tilde{\omega}(X_1,\ldots,X_{2i-1})\ .
\end{align*}
The fourth equality above is because any involution on $\mathcal{M}_n(k)$ is of the form $X \mapsto J^{-1}X^TJ$ for some $J \in \GL_n(k)$ satisfying $J^T=\pm J$ (see \cite[Thm. 1]{AA}), which implies that any involution on $\mathcal{M}_n(k)$ is trace preserving. Hence, $\sigma(\omega_{4i-3})=\omega_{4i-3}$ and $\sigma(\omega_{4i-1})=-\omega_{4i-1}$ for all $i \geq 1$. As in the proof of Corollary \ref{hosym}, it follows that the $+1$-eigenspace of the induced skew involution on $\mathrm H^{\bullet}(\gl_n(k);k)$ is $\Lambda^{\rm odd}(\omega_1,\omega_5,\ldots,\omega_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\omega_3,\omega_7,\ldots,\omega_{4\lfloor \frac{n-3}{4}\rfloor+3})$. Taking graded linear duals, it follows that 
$$\overline{\mathrm{H}}^{\rm ev}_{\bullet}(\gl_n(k);k) \,\cong\, \Lambda^{\rm odd}(\xi_1,\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\ .$$ The desired formula for ${\rm HO}_\bullet(U\gl_n(k))$ then follows immediately from Theorem \ref{houainv}. The proof of the formula for ${\rm HO}_\bullet(U\mathfrak{sl}_n(k))$ is identical but for one minor modification: the (co)generators $\omega_1$ and $\xi_1$ are omitted.
\end{proof}

\la{hougl}
For any involution on $\gl_n(k)$ that is the restriction of an involution on $\mathcal{M}_n(k)$ as above,

\begin{align*}
   {\rm HO}_\bullet(U\gl_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_1,\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\,,\\
    {\rm HO}_\bullet(U\mathfrak{sl}_n(k)) &\cong\,\bigwedge_k\left[\big(\Lambda^{\rm odd}(\xi_5,\ldots,\xi_{4\lfloor \frac{n-1}{4}\rfloor+1}) \otimes \Lambda(\xi_3,\xi_7,\ldots,\xi_{4\lfloor \frac{n-3}{4}\rfloor+3})\big)[-1]\right]\ .
\end{align*}

\la{grHDdef}
For $\Gamma \in \sGrh$, we define $B^{\rm dih}\Gamma := \Psidih^\ast(\Gamma): \Delta D^{\rm op} \to \sSet$ and

$$ \mathrm{HD}_\bullet(k[\Gamma])\,:=\,{\rm Tor}^{\Delta D^{\rm op}}_\bullet\big(k, k[B^{\rm dih}\Gamma]\big)\,\cong\,{\rm Tor}^{\Delta D}_\bullet\big(k[B^{\rm dih}\Gamma], k\big)\ . $$

\la{grchardef}
For $P \in \mathcal{O}(G)^{G,\iota}$, the {\it dihedral character map} associated with $P$ is the composite

$$ \chi^{\rm dih}_{G,P}(\Gamma)_\bullet:\ \mathrm{HD}_\bullet(k[\Gamma]) \xrightarrow{(\Delta_G P)_\ast} {\rm Tor}^{\Delta D}_\bullet\big(k[B^{\rm dih}\Gamma], B_{\rm dih}\mathcal{O}(G)\big) \xrightarrow{\ \Psidih^\ast\ } {\rm HR}_\bullet(\Gamma, G)\ . $$

\la{grtraces}
We illustrate Definition~\ref{grchardef} in some special cases:
\begin{itemize}
\item[$(1)$] Let $G = {\rm GL}_n$, $P = {\rm{Tr}}_n$. Since ${\rm{Tr}}_n(g^{-1}) \neq {\rm{Tr}}_n(g)$, the derived character map ${\rm{Tr}}_n(\Gamma)_\bullet: {\rm HC}_\bullet(k[\Gamma]) \to {\rm HR}_\bullet(\Gamma, {\rm GL}_n)$ of \cite{BR22} does not factor through $\mathrm{HD}_\bullet(k[\Gamma])$ ({\it cf.} \cite[Remark 3.2]{BR22c}).

\item[$(2)$] Let $G = \GLm$, $P = {\rm{Tr}}_n|_{G}$. Now ${\rm{Tr}}_n(g^{-1}) = {\rm{Tr}}_n(\sigma(g)) = {\rm{Tr}}_n(g)$, since $\sigma$ is trace preserving, so that ${\rm{Tr}}_n$ defines a dihedral character map ${\rm{Tr}}^\sigma_n(\Gamma)_\bullet: \mathrm{HD}_\bullet(k[\Gamma]) \to {\rm HR}_\bullet(\Gamma, \GLm)^{\GLm}$. The isomorphism of Proposition~\ref{grcomp} identifies this with the involutive derived character map \eqref{DTr} of the involutive algebra $k[\Gamma]$ (cf. \cite[Remark 3.16]{BR22} in the cyclic case).

\item[$(3)$] Let $n = 1$, $G = \mtwo$, $\mathcal{O}(\mtwo) = k \cdot 1 \oplus k \cdot x$. Here $\iota = {\rm{Id}}$ on $\mtwo$, so that $\mathcal{O}(\mtwo)^{\mtwo,\iota} = \mathcal{O}(\mtwo)$; the function $P = x$ defines the {\it one-dimensional involutive derived character map} 
\begin{equation} \la{grTr} 
{\rm{Tr}}^\sigma(\Gamma)_\bullet:\ \mathrm{HD}_\bullet(k[\Gamma]) \to {\rm HR}_\bullet(\Gamma, \mtwo)\ .
\end{equation}










\end{itemize}

\la{Tgroups}
Let $k$ be a commutative ring and ${\mathcal A}$ an abelian group. For any $\Gamma \in \sGrh$, there is a weak equivalence of spaces, natural in $\Gamma$,

\begin{equation} \la{XAeq} X^{{\mathcal A}}_\Gamma\,\simeq\,\Omega\,\SPi(B\Gamma;{\mathcal A})\,, \end{equation}

and consequently a natural isomorphism

\begin{equation} \la{HRDA} {\rm HR}_\bullet(\Gamma, D_k({\mathcal A}))\,\cong\,\mathrm H_\bullet\big(\Omega\,\SPi(B\Gamma;{\mathcal A});\,k\big)\,\cong\,\mathrm H_\bullet\Big(\prod_{n \geq 1} K\big(\tilde{\mathrm H}_n(B\Gamma;{\mathcal A}), n-1\big);\,k\Big)\ . \end{equation}

In particular, ${\rm HR}_0(\Gamma, D_k({\mathcal A})) = k[\pi_0(\Gamma)_{\rm ab} \otimes {\mathcal A}]$, and if $k \supseteq \mathbb{Q}$ and ${\mathcal A}$ is a torsion group, then ${\rm HR}_\bullet(\Gamma, D({\mathcal A})) \cong k[\mathrm H_1(B\Gamma; {\mathcal A})]$ is concentrated in degree $0$.

\la{grHOdef}
For $\Gamma \in \sGrh$, put $B_{\rm hOct}\Gamma := \Psihyp^\ast(\Gamma): \Delta H \to \sSet$ and

$$ \mathrm{HO}_\bullet(k[\Gamma])\,:=\,{\rm Tor}^{\Delta H}_\bullet\big(k, k[B_{\rm hOct}\Gamma]\big)\ . $$

\la{grlift}
Let $\fG_{\mathbb{Z}/2} := \fG_{F_{\mathbb{Z}/2}}$ be the category of elements of \eqref{Z2}. The functor $\Psihyp$ lifts to a functor

\begin{equation} \la{tPsihyp} \tPsihyp:\ \Delta H \to \fG_{\mathbb{Z}/2}^{\rm op}\,,\qquad [n] \mapsto (\langle n+1 \rangle;\, \bar{1}, \ldots, \bar{1})\,, \end{equation}

and hence, for every $\Gamma \in \sGrh$, induces a natural map $\tPsihyp^\ast: \mathrm{HO}_\bullet(k[\Gamma]) \to {\rm HR}_\bullet(\Gamma, \mtwo)$ such that ${\rm{Tr}}^\sigma(\Gamma)_\bullet = \tPsihyp^\ast \circ i^\ast$, where ${\rm{Tr}}^\sigma(\Gamma)_\bullet$ is the one-dimensional involutive derived character map \eqref{grTr}.

\la{grspaces}
The maps $\mathrm{HD}_\bullet(k[\Gamma]) \xrightarrow{i^\ast} \mathrm{HO}_\bullet(k[\Gamma]) \xrightarrow{\tPsihyp^\ast} {\rm HR}_\bullet(\Gamma,\mtwo)$ are induced on homology by the natural maps of spaces

\begin{equation} \la{grmaps} \big|\hocolim_{\Delta D^{\rm op}}B^{\rm dih}\Gamma\big| \xrightarrow{\ \ i\ \ } \big|\hocolim_{\Delta H}B_{\rm hOct}\Gamma\big| \xrightarrow{\ \tPsihyp\ } \big|\hocolim_{\fG_{\mathbb{Z}/2}^{\rm op}}\, p^\ast\Gamma\big|\,\simeq\,\Omega\,\SPi(B\Gamma;\mathbb{Z}/2)\,, \end{equation}

the last equivalence being Theorem~\ref{Tgroups}. For a discrete group $\Gamma$, the middle space is the bar construction $B(C_\infty E, C_1, \Gamma)$ of \cite[Theorem 7.20]{G21}, where $E := EC_{2+}\wedge_{C_2}(\,\mbox{--}\,)$, and the left space is $EO(2)\times_{O(2)}\mathcal{L}(B\Gamma)$ \cite{Lo}.

\la{grex}
We illustrate Corollary~\ref{Cgroups} in some interesting spacial cases:
\begin{itemize}
\item[$(1)$]
 $\Gamma = \mathbb{Z}$: $\mathrm{HO}_\bullet(k[x^{\pm1}])$, with $\bar{x} = x^{-1}$, is $k[x]/(x^2-1) \cong k^2$ concentrated in degree $0$. Directly: $\mathrm{HO}_0 = k[x^{\pm1}]/(x - x^{-1})$ by \cite[Theorem 6.8]{G22}, and ${\rm HR}_\bullet(\mathbb{Z},\mtwo) = \mathcal{O}(\mtwo)$ since $k[\mathbb{Z}]$ is a representable $\fG^{\rm op}$-module. 

\item[$(2)$] $\Gamma = \mathbb{Z}/2$: the involution on $k[\mathbb{Z}/2]$ is trivial, and $\mathrm{HO}_\bullet(k[\mathbb{Z}/2]) = k[\mathbb{Z}/2]$ in degree $0$, matching $k[\mathrm H_1(B\mathbb{Z}/2;\mathbb{Z}/2)] = k[\mathbb{Z}/2]$.

\item[$(3)$] $B\Gamma$ simply connected of finite type: then $k[\Gamma] \simeq U\mathfrak{a}$ for a Quillen Lie model $\mathfrak{a}$ of $B\Gamma$, with the inversion corresponding to the involution $\sigma = -{\rm{Id}}$ on $\mathfrak{a}$, and Theorem~\ref{houainv} gives $\mathrm{HO}_\bullet(U\mathfrak{a}) = k$, in agreement with $k[\mathrm H_1(B\Gamma;\mathbb{Z}/2)] = k$. Note that in comparison with \cite[Theorem 1.3]{BR22c}, ${\rm HS}_\bullet(U\mathfrak{a}) = \Lambda_k[\overline{\mathrm{H}}_{\bullet+1}(\mathfrak{a};k)]$ is large, while its involutive shadow is trivial, the sign $(-1)^{p-1}\Lambda^p(-{\rm{Id}}) = -1$ killing all of the reduced Chevalley-Eilenberg homology.

\item[$(4)$] $\Gamma = F_m$ a free group: $\mathrm{HO}_\bullet(k[F_m]) = k[(\mathbb{Z}/2)^m] = \mathcal{O}(\mtwo^m)$ in degree $0$. Combined with Theorem~\ref{T1a}, this is the vanishing ${\rm HR}^{\ast}_i(k[F_m], k) = 0$, $i > 0$, used in the proof of Proposition~\ref{grcomp}. Hence, using Remark~\ref{grrational}, the case $n=1$ of Proposition~\ref{grcomp} can be obtained without appealing to \cite[Theorem 1.7]{BR14}.
\end{itemize}
